tools.example:
for tol = {'1e-3','1e-5','1e-7'}
    out = sim(mdl, 'RelTol', tol{1});
end

set_param(mdl, 'SolverType', 'Fixed-step', 'Solver', 'ode4', 'FixedStep', 'auto');
set_param(mdl, 'SimulationCommand', 'update');
get_param(mdl, 'CompiledStepSize')   % step size chosen by 'auto'

set_param(mdl, 'FastRestart', 'on');
for k = 1:20
    Kp = k/10;          % tunable workspace variable
    out(k) = sim(mdl);
end
set_param(mdl, 'FastRestart', 'off');

set_param(mdl, 'ExtMode', 'on');
slbuild(mdl);
% start the executable on the target, then:
set_param(mdl, 'SimulationMode', 'external');
set_param(mdl, 'SimulationCommand', 'connect');
set_param(mdl, 'SimulationCommand', 'start');
